// Quelle: https://www.printables.com/model/1810383-fully-parametric-gear-generator-circular-bevel-gea/files
// =================================================================
// --- PARAMETERS CONFIGURATION ---
// =================================================================

// Mode selector: Use "circular" for flat gear or "bevel" for cone gear
//gear_type       = "circular"; // Choose either "circular" or "bevel"

// General gear parameters
//tooth_pitch     = 5;      // Tooth Pitch
//pressure_angle  = 15.5;   // Pressure Angle
//addendum        = 1.5;    // Addendum height
//dedendum        = 1.5;    // Dedendum height

// Circular Gear parameters
//circular_tooth_count = 7; // Number of teeth
//circular_height      = 11; // Extrusion height (gear thickness)
//bore_diameter        = 2;  // Central bore hole diameter

// Bevel Gear parameters
bevel_tooth_count    = 20; // Number of teeth
bevel_angle          = 45; // Pitch cone angle
bevel_width          = 5;  // Face width of the gear blank

// Geometry system variables
xw = 2; // Extra wall thickness for the bore hole
pi = 3.141592654;

// =================================================================
// --- INTERNAL FUNCTIONS AND MODULES (DO NOT MODIFY) ---
// =================================================================

function toothOffset(toothHeight, toothWidth, traversedDist) = 
    (abs((traversedDist % toothWidth) - (toothWidth/2)) - toothWidth/4) * (toothHeight / toothWidth);

function mapTooth(pt, normAng, toothHeight, toothWidth, traversedDist) = [
    pt[0] + cos(normAng) * toothOffset(toothHeight, toothWidth, traversedDist), 
    pt[1] + sin(normAng) * toothOffset(toothHeight, toothWidth, traversedDist)
];

function mapBevel(sr, gr, theta, toothHeight, toothWidth, traversedDist) = 
    (sr - toothOffset(toothHeight, toothWidth, traversedDist)) * [cos(theta), sin(theta)];

function getNormal(p1, p2) = atan2((p2-p1)[1], (p2-p1)[0]) + 90;

function cumDist(distPath, distArray = [0]) = 
    (len(distArray) >= len(distPath)) ? distArray : cumDist(distPath, concat(distArray, [norm(distPath[len(distArray)-1] - distPath[len(distArray)]) + distArray[len(distArray)-1]]));

module bevelTooth(gearRadius, bevelAngle, bevelWidth, toothHeight, toothWidth, $fn=60){
    gr = gearRadius;
    tw = toothWidth;
    ta = (tw / (pi * 2 * gr)) * 360; 
    tdd = toothWidth / ta; 
    toothCurve = [for (theta = [(-ta/2):(ta/$fn):(ta/2)]) mapBevel(sr=gr / sin(bevelAngle), gr=gearRadius, theta=theta, toothHeight=toothHeight, toothWidth=toothWidth, traversedDist=(theta+ta/2)*tdd)];
    rotate([0,-bevelAngle,0]) linear_extrude(height=bevelWidth, center=true) polygon(points=toothCurve);
}

module toothExtrude(extrudePath, toothWidth, toothHeight){
    extrudePathDist = cumDist(extrudePath);
    toothPath = [for (i = [1 : (len(extrudePath)-1)] ) mapTooth((extrudePath[i-1]+extrudePath[i])/2, getNormal(extrudePath[i-1],extrudePath[i]), toothHeight=toothHeight, toothWidth=toothWidth, traversedDist = (extrudePathDist[i-1] + extrudePathDist[i])/2)];
    polygon(points = toothPath);
}

module circularGear(radius = -1, toothPitch = -1, toothCount = 7, addendum = 7, dedendum = 6, pressureAngle = 15.5){
    if(((radius == -1) && (toothPitch == -1)) || ((radius != -1) && (toothPitch != -1))){
        echo("one (and only one) of radius or toothPitch must be specified");
    }
    tw = (toothPitch == -1) ? 2 * radius * pi / toothCount : toothPitch;
    gr = (radius == -1) ? (tw * toothCount) / (2 * pi) : radius;
    union(){
        intersection(){
            th = (tw/2) / tan(pressureAngle);
            toothExtrude(extrudePath = [for (t = [-180:(360/(toothCount*16)):180]) [cos(t), sin(t)]*gr], toothWidth = tw, toothHeight = th);
            circle(r=gr+addendum, $fn=360);
        }
        circle(r=gr-dedendum, $fn=360);
    }
    echo("Circular Gear -> Tooth width: ", tw, "Radius: ", gr);
}

module bevelGear(radius = -1, toothPitch = -1, bevelAngle = 45, width = 5, toothCount = 20, addendum = 1.5, dedendum = 1.5, pressureAngle = 15.5){
    if(((radius == -1) && (toothPitch == -1)) || ((radius != -1) && (toothPitch != -1))){
        echo("one (and only one) of radius or toothPitch must be specified");
    }
    tw = (toothPitch == -1) ? 2 * radius * pi / toothCount : toothPitch;
    gr = (radius == -1) ? (tw * toothCount) / (2 * pi) : radius;

    gr1 = gr - cos(bevelAngle) * width/2; 
    gr2 = gr + cos(bevelAngle) * width/2; 
    tw1 = 2 * gr1 * pi / toothCount;
    tw2 = 2 * gr2 * pi / toothCount;
    th = tw / (pi/6); 
    th1 = tw1 / (pi/6); 
    th2 = tw2 / (pi/6); 
    sr = gr / sin(bevelAngle); 
    so = gr / tan(bevelAngle); 
    so1 = gr1 / tan(bevelAngle); 
    so2 = gr2 / tan(bevelAngle); 

    intersection(){
        for(i = [0:(toothCount-1)]){
            rotate(360*i / toothCount){
                hull(){
                    translate([0,0,-so1+sin(bevelAngle)*width/2]) bevelTooth(gearRadius=gr1, bevelAngle=bevelAngle, bevelWidth=0.01, toothHeight=th1, toothWidth=tw1, $fn=60);
                    translate([0,0,-so]) bevelTooth(gearRadius=gr, bevelAngle=bevelAngle, bevelWidth=0.01, toothHeight=th, toothWidth=tw, $fn=60);
                    translate([0,0,-so2-sin(bevelAngle)*width/2]) bevelTooth(gearRadius=gr2, bevelAngle=bevelAngle, bevelWidth=0.01, toothHeight=th2, toothWidth=tw2, $fn=60);
                }
            }
        }
        translate([0,0,-so]) sphere(r=sr+addendum, $fn = toothCount*4);
    }
    cr1 = gr1 - sin(bevelAngle) * dedendum;
    cr2 = gr2 - sin(bevelAngle) * dedendum;
    translate([0,0,-cos(bevelAngle) * dedendum]) cylinder(r2=cr1, r1=cr2, h=cos(bevelAngle) * width, center=true);
    echo("Bevel Gear -> Tooth width: ", tw, "Radius: ", gr);
}

// =================================================================
// --- MODEL ASSEMBLY AND OUTPUT ---
// =================================================================

if (gear_type == "circular") {
    // Render Circular Gear
    linear_extrude(height=circular_height){
        difference(){
            circularGear(
                toothPitch=tooth_pitch, 
                toothCount=circular_tooth_count, 
                addendum=addendum, 
                dedendum=dedendum, 
                pressureAngle=pressure_angle
            );
            circle(d=bore_diameter+xw, $fn=60);
        }
    }
} else if (gear_type == "bevel") {
    // Render Bevel Gear
    difference() {
        bevelGear(
            toothPitch=tooth_pitch, 
            bevelAngle=bevel_angle, 
            width=bevel_width, 
            toothCount=bevel_tooth_count, 
            addendum=addendum, 
            dedendum=dedendum, 
            pressureAngle=pressure_angle
        );
        cylinder(d=bore_diameter, h=bevel_width*4, center=true, $fn=60);
    }
} else {
    echo("ERROR: Unknown gear_type! Please choose 'circular' or 'bevel'.");
}

